.stringn "#F00#C02플레이 방법을 안내받을 수 있습니다.\x11\x10#F00#C02지침이란, 새롭게 나오는 기능을\n"
.stringn "#F00#C02안내역인 안나가 시범을 보여서\n"
.stringn "#F00#C02설명해 주는 것입니다.\x11\x10#F00#C02한 번 본 지침은\n"
