.stringn "なんだ、誰もいないじゃないか"
db 0
.align 4
//MMC_SCENE0101_05

//0x22780
Text_22760:
.stringn "おかしいな。このあたりで物音がしたと思ったんだが\x02mc…\x02md"
db 0
.align 4
//MMC_SCENE0101_06

//0x227BC
Text_2279C:
.stringn "\x02mc…\x02mdだめ、ユンヌ\x02mc！\x02md　じっとして\x02mc…\x02md"
db 0
.align 4
//MMC_SCENE0101_07

//0x227F0
Text_227D0:
.stringn "ユンヌ。お願いだから、おとなしくし\x02mc…\x02md"
db 0
.align 4
//MMC_SCENE0101_08

//0x2281C
Text_227FC:
.stringn "ピィ\x02mc！\x02md"
db 0
.align 4
//MMC_SCENE0101_09

//0x2282C
Text_2280C:
.stringn "誰かいるのかっ\x02mc！？\x02md"
db 0
.align 4
//MMC_SCENE0101_10

//0x22848
Text_22828:
.stringn "どうした？　【暁の団】のやつらか\x02mc！？\x02md"
db 0
.align 4
//MMC_SCENE0101_11

//0x22874
Text_22854:
.stringn "いや、寝ぼけた野鳥が飛び出したようだ"
db 0
.align 4
//MMC_SCENE0101_12

//0x2289C
Text_2287C:
.stringn "ははははは　捕まえたぜ\x02mc！\x02md"
db 0
.align 4
//MMC_SCENE0101_13

//0x228BC
Text_2289C:
.stringn "お\x02mc…　\x02mdもっとよく見せてみろ"
db 0
.align 4
//MMC_SCENE0101_14

//0x228E0
Text_228C0:
.stringn "この娘は\x02mc…\x02md例の占い師じゃないか？"
db 0
.align 4
//MMC_SCENE0101_15

//0x22908
Text_228E8:
.stringn "【은발의 소녀】とか【치유의 손】って\n"
.stringn " たいそうな二つ名をもつあれか？\n"
.stringn " なんだ、こんな普通の小娘だったとはな"
db 0
.align 4
//MMC_SCENE0101_16

//0x22974
Text_22954:
.stringn "どちらにせよ、手柄は俺たちの部隊のものだ。\n"
.stringn "【새벽단】など、こいつを除けばただの盗っ人集団にすぎん"
db 0
.align 4
//MMC_SCENE0101_17

//0x229D8
Text_229B8:
.stringn "さっそく、隊長のもとへ連行しようぜ"
db 0
.align 4
//MMC_SCENE0101_18

//0x229FC
Text_229DC:
.stringn "この縄で縛れ"
db 0
.align 4
//MMC_SCENE0101_19

//0x22A0C
Text_229EC:
.stringn "よし。\n"
.stringn "いいかデインの小娘。\n"
.stringn "痛い思いをしたくなければ暴れるんじゃないぞ？"
db 0
.align 4
//MMC_SCENE0101_20

//0x22A58
