//0x20268
Text_20248:
.stringn "산속의 전투"
db 0
.align 4
//MTM_TRI_MAP1

//0x20274
Text_20254:
.stringn "산길을 지나던 아이크 일행에게\n"
.stringn "갑자기 정체불명의 군이 덤벼들었다.\n"
.stringn "점점 평화로워지는 이때에\n"
.stringn "그들을 방치할 수는 없다.\n"
.stringn "아이크는 응전하기로 결정했다."
db 0
.align 4
//MTM_TRI_MAP1_EX

//0x2030C
Text_202EC:
.stringn "외딴섬에서의 전투"
db 0
.align 4
//MTM_TRI_MAP2

//0x2031C
Text_202FC:
.stringn "데인 왕국이 크리미아에 남긴 대량의 물자는\n"
.stringn "일단 작은 섬에 보관하기로 결정했다.\n"
.stringn "아이크 일행은 그 호위를 맡게 되었지만\n"
.stringn "정보를 안 자들이 습격해 왔다.\n"
.stringn "원군이 도착할 때까지 버틸 수 있을까?"
db 0
.align 4
//MTM_TRI_MAP2_EX

//0x203F0
Text_203D0:
.stringn "싸우는 도중"
db 0
.align 4
//MTM_TRI_MAP3

//0x203FC
Text_203DC:
.stringn "포로 반환을 요구한 아이크 일행에게\n"
.stringn "적은 뜻밖의 조건을 내걸었다.\n"
.stringn "「우리가 지정한 자들과 싸워라.\n"
.stringn " 살아남으면 포로들을 풀어 주마.」\n"
.stringn "아이크는 요구를 받아들였다."
db 0
.align 4
//MTM_TRI_MAP3_EX

//0x204B4
Text_20494:
.stringn "장성의 결사대"
db 0
.align 4
//MTM_TRI_MAP4

//0x204C4
Text_204A4:
.stringn "데인-베그니온의 국경에 산적단이 나타났다.\n"
.stringn "산적들은 인근 주민을 인질로 잡고 금품을\n"
.stringn "요구하면서 시간 안에 내놓지 않으면 인질들을\n"
.stringn "죽이겠다고 했다. 아이크 일행은 눈에 안 띄는\n"
.stringn "소수로 장성을 돌파, 인질 구출에 나서기로 했다."
db 0
.align 4
//MTM_TRI_MAP4_EX

//0x20594
Text_20574:
.stringn "감옥 탈출"
db 0
.align 4
//MTM_TRI_MAP5

//0x205A4
Text_20584:
.stringn "데인 잔병의 함정에 빠진 아이크 일행은\n"
.stringn "사로잡히고 만다.\n"
.stringn "그런데 적도 당황했는지\n"
.stringn "무기를 빼앗지도 않고 감옥에 가뒀다.\n"
.stringn "아이크 일행은 탈출하기로 결심했다."
db 0
.align 4
//MTM_TRI_MAP5_EX

//0x20640
Text_20620:
.stringn "선상의 함정"
db 0
.align 4
//MTM_TRI_MAP6

//0x2064C
Text_2062C:
.stringn "그 두 배는 아무것도 아닌 것처럼 보였다.\n"
.stringn "그러나 선원들은 교묘한 말로\n"
.stringn "아이크 일행을 분산시킨 뒤 공격해 왔다.\n"
.stringn "아이크는 동료들이 돌아올 때까지\n"
.stringn "열심히 방어전을 펼쳐야 한다."
db 0
.align 4
//MTM_TRI_MAP6_EX

